        foreach ($items as $item) {
            // Re-resolve duty IDs if empty or to ensure sync with current schedule
            if (!empty($item['departure_at'])) {
                $dep = Carbon::parse($item['departure_at']);
                if (empty($item['pegawai_id']) && !empty($item['observer_name'])) {
                    $resolvedObserver = $resolver->resolvePegawai($dep->toDateTimeString(), $item['observer_name']);
                    if ($resolvedObserver) {
                        $item['pegawai_id'] = $resolvedObserver->id;
                    }
                }
                if (empty($item['teknisi_id'])) {
                    $resolvedTeknisi = $resolver->getTeknisiByTimestamp($dep->toDateTimeString(), 'UTC');
                    if ($resolvedTeknisi) {
                        $item['teknisi_id'] = $resolvedTeknisi->id;
                    }
                }
                if (empty($item['ppnpn_id'])) {
                    $resolvedPpnpn = $resolver->getPpnpnByTimestamp($dep->toDateTimeString(), 'UTC');
                    if ($resolvedPpnpn) {
                        $item['ppnpn_id'] = $resolvedPpnpn->id;
                    }
                }
            }

            DataFlightDocument::updateOrCreate(
                [
                    'inasiam_fd_id' => $item['inasiam_fd_id'] ?? $item['no_fd'],
                ],
                $item
            );
        }
    }
